static bool dust_ok(u64 their_dust, u64 our_reserve)
{
	struct channel_config remoteconf, localconf;
	char *err;

	memset(&remoteconf, 0, sizeof(remoteconf));
	memset(&localconf, 0, sizeof(localconf));
	remoteconf.dust_limit = amount_sat(their_dust);
	localconf.channel_reserve = amount_sat(our_reserve);

	if (check_dust_limit(tmpctx, &remoteconf, &localconf, &err))
		return true;
	assert(strstr(err, "would be above our reserve"));
	return false;
}

int main(int argc, char *argv[])
{
	common_setup(argv[0]);

	assert(dust_ok(546, 10000));
	assert(dust_ok(10000, 10000));

	assert(!dust_ok(10001, 10000));
	assert(!dust_ok(2100000000000000ULL, 10000));

	common_shutdown();
	return 0;
}
